        n = len(nums)
        result = float('inf')

        for i in range(n - x):
            left = nums[i]
            right = sorted(nums[i + x:])
            idx = bisect.bisect_left(right, left)

            if idx < len(right):
                result = min(result, abs(left - right[idx]))
            if idx > 0:
