class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        left = [1] * n
        right = [1] * n

        for i in range(1, n):
            if maxHeights[i] >= maxHeights[i - 1]:
                left[i] = left[i - 1] + 1
            else:
                count = 1
                for j in range(i - 1, -1, -1):
                    if maxHeights[j] <= maxHeights[i]:
                        count += 1
                    else:
                        break
                left[i] = count

        for i in range(n - 2, -1, -1):
            if maxHeights[i] >= maxHeights[i + 1]:
                right[i] = right[i + 1] + 1
            else:
                count = 1
                for j in range(i + 1, n):
                    if maxHeights[j] <= maxHeights[i]:
                        count += 1
                    else:
                        break
                right[i] = count

        max_sum = 0
        for i in range(n):
            max_sum = max(max_sum, sum(maxHeights[j] * min(left[j], right[j]) for j in range(i - left[i] + 1, i + right[i])))

        return max_sum

