class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)
        dp = [1] * n
        char_count = defaultdict(int)

        for i in range(n):
            char_count[s[i]] += 1
            max_count = max(char_count.values())
            if max_count > k:
                for j in range(i):
                    char_count[s[j]] -= 1
                    if char_count[s[j]] == 0:
                        del char_count[s[j]]
                    max_count = max(char_count.values())
                    if max_count <= k:
                        dp[i] = max(dp[i], dp[j] + 1)
                        break

        return max(dp)

