    # Check if the length of the strings is M
    if any(len(s) != M for s in strings):
        return "No"

    # Check if the strings are pairwise distinct
    if len(set(strings)) != N:
        return "No"

    # Check if the strings can be rearranged to satisfy the condition
    for i in range(N - 1):
        for j in range(M):
            if strings[i][j] != strings[i + 1][j]:
                return "Yes"

    return "No"

