import sys

def transform_to_identity(N, A):
    operations = []
    for i in range(N):
        if A[i] != i + 1:
            # Find the position of the correct element
            correct_pos = A.index(i + 1)
            # Perform the swap
            A[i], A[correct_pos] = A[correct_pos], A[i]
            operations.append((i + 1, correct_pos + 1))
    return len(operations), operations

def main():
