class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Helper function to calculate the maximum sum of non-adjacent subsequence
        def max_non_adjacent_sum(nums):
            if not nums:
                return 0
            if len(nums) == 1:
                return nums[0]

            dp = [0] * len(nums)
            dp[0] = nums[0]
            dp[1] = max(nums[0], nums[1])

            for i in range(2, len(nums)):
                dp[i] = max(dp[i - 1], dp[i - 2] + nums[i])

            return dp[-1]

        # Precompute the maximum sum for each position
        max_sums = [0] * n
        for i in range(n):
            max_sums[i] = max_non_adjacent_sum(nums[:i] + [nums[i]] + nums[i + 1:])

        result = 0
        for pos, x in queries:
            result = (result + (max_sums[pos] + x) % MOD) % MOD

        return result

