class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        peaks = []

        # Find all peaks in the array
        for i in range(1, n - 1):
            if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                peaks.append(i)

        result = []

        for query in queries:
            if query[0] == 1:
                l, r = query[1], query[2]
                count = sum(1 for peak in peaks if l <= peak <= r)
                result.append(count)
            elif query[0] == 2:
                index, val = query[1], query[2]
                if index > 0 and index < n - 1 and nums[index] > nums[index - 1] and nums[index] > nums[index + 1]:
                    peaks = [peak for peak in peaks if peak != index]
                nums[index] = val
                # Re-find peaks after the change
                peaks = []
                for i in range(1, n - 1):
                    if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                        peaks.append(i)

        return result

