from collections import defaultdict, deque

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = deque([(0, start)])
    while queue:
        current_distance, current_node = queue.popleft()
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                queue.append((distance, neighbor))
    return distances

def solve_queries(N, M, bridges, Q, queries):
    graph = defaultdict(dict)
    for U, V, T in bridges:
        graph[U][V] = T
        graph[V][U] = T

    results = []
    for K, bridge_indices in queries:
        visited = [False] * (N + 1)
        visited[1] = True
        time = 0
        for bridge_index in bridge_indices:
            U, V = bridges[bridge_index - 1]
            if not visited[U]:
                time += dijkstra(graph, U)[V]
                visited[U] = True
            if not visited[V]:
                time += dijkstra(graph, V)[U]
                visited[V] = True
        results.append(time)

    return results

def main():
    N, M = map(int, input().split())
