class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        def prime_factors(n):
            factors = set()
            for i in range(2, int(n**0.5) + 1):
                while n % i == 0:
                    factors.add(i)
                    n //= i
            if n > 1:
                factors.add(n)
            return factors

        graph = defaultdict(list)
        for num in nums:
            if num > threshold:
                continue
            for factor in prime_factors(num):
                if factor <= threshold:
                    graph[num].append(factor)
                    graph[factor].append(num)

        visited = set()
        count = 0

        for num in nums:
            if num > threshold or num in visited:
                continue
            count += 1
            stack = [num]
            while stack:
                node = stack.pop()
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)

        return count

