class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def digit_sum(s):
            return sum(int(digit) for digit in s)

        def count_good(start, end, min_sum, max_sum):
            if start > end:
                return 0

            if digit_sum(start) > max_sum:
                return 0

            if digit_sum(start) < min_sum:
                return count_good(str(int(start) + 1), end, min_sum, max_sum)

            if start == num2:
                return sum(1 for digit in num2 if int(digit) >= min_sum)

            count = 0
            if digit_sum(start) == min_sum:
                count += int(num2) - int(start) + 1

            for i in range(10):
                if i > int(start[-1]):
                    count += count_good(start[:-1] + str(i), end, min_sum, max_sum)
                else:
                    count += count_good(start[:-1] + str(i), start, min_sum, max_sum)

            return count % MOD

        return (count_good(num1, num2, min_sum, max_sum) - count_good(num1, str(int(num1) - 1), min_sum, max_sum)) % MOD

