class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        prime_factors = defaultdict(set)

        for num in nums:
            if num == 1:
                return False
            for i in range(2, int(num**0.5) + 1):
                while num % i == 0:
                    prime_factors[i].add(num)
                    num //= i
            if num > 1:
                prime_factors[num].add(num)

        connected_components = defaultdict(set)

        for num, factors in prime_factors.items():
            for factor in factors:
                connected_components[factor].update(factors)

        visited = set()

        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            for neighbor in connected_components[node]:
                dfs(neighbor)

        for num in nums:
            if num not in visited:
                dfs(num)
                if len(visited) == len(nums):
                    return True

        return False

