        n = len(s)

        @lru_cache(None)
        def is_semi_palindrome(i, j):
            if i >= j:
                return True
            if s[i] != s[j]:
                return False
            return is_semi_palindrome(i + 1, j - 1)

        @lru_cache(None)
        def dp(i, k):
            if k == 1:
                return sum(not is_semi_palindrome(i, j) for j in range(i + 1, n + 1))
            res = float('inf')
            for j in range(i + 1, n - k + 2):
                res = min(res, dp(j, k - 1) + sum(not is_semi_palindrome(i, j - 1)))
            return res

