        count = [0] * 26
        for word in words:
            for char in word:
                count[ord(char) - ord('a')] += 1

        count.sort()
        odd_count = sum(1 for c in count if c % 2 == 1)
        even_count = sum(c // 2 for c in count)

        result = 0
        for i in range(len(words)):
            if len(words[i]) % 2 == 0:
                if even_count >= len(words[i]) // 2:
                    even_count -= len(words[i]) // 2
                    result += 1
                else:
                    break
            else:
                if odd_count > 0 and even_count >= len(words[i]) // 2:
                    odd_count -= 1
                    even_count -= len(words[i]) // 2
                    result += 1
                else:
                    break

        return result

