from collections import deque

def is_valid(x, y, H, W):
    return 0 <= x < H and 0 <= y < W

def bfs(grid, start, goal, T):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(start, 0, 0)])
    visited = set()
    visited.add(start)

    while queue:
        (x, y, candy_count) = queue.popleft()
        if (x, y) == goal:
            return candy_count

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, H, W) and grid[nx][ny] != '#' and (nx, ny) not in visited:
                if grid[nx][ny] == 'o':
                    queue.append((nx, ny, candy_count + 1))
                else:
                    queue.append((nx, ny, candy_count))
                visited.add((nx, ny))

        if queue and queue[0][1] == T:
            return -1

    return -1

