def find_guarded_vertices(N, M, K, edges, guards):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    guarded = set()
    for p, h in guards:
        queue = [(p, 0)]
        visited = set()
        while queue:
            v, dist = queue.pop(0)
            if v in visited:
                continue
            visited.add(v)
            if dist <= h:
                guarded.add(v)
            for neighbor in graph[v]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))

    return sorted(guarded)

