def is_valid_path(H, W, S):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    target_sequence = ['s', 'n', 'u', 'k', 'e']

    def dfs(x, y, path):
        if len(path) == H * W + 1:
            return path[-1] == target_sequence[0]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W:
                if dfs(nx, ny, path + [S[nx][ny]]):
                    return True
        return False

    return dfs(0, 0, ['s'])

