from collections import defaultdict

def max_path_length(N1, N2, M, edges):
    # Create adjacency list for the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Check if there is a path from 1 to N1+N2
    def bfs(start):
        visited = [False] * (N1 + N2 + 1)
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited[N1 + N2]

    if bfs(1):
        return 0  # No need to add an edge if already connected

    # Find the maximum path length by adding an edge
    max_length = 0
    for u in range(1, N1 + 1):
        for v in range(N1 + 1, N1 + N2 + 1):
            if (u, v) not in edges and (v, u) not in edges:
                new_edges = edges + [(u, v)]
                if bfs(1):
                    max_length = max(max_length, len(new_edges) - 1)
    return max_length

