def find_directed_cycle(N, A):
    from collections import defaultdict

    # Build the graph
    graph = defaultdict(list)
    for i in range(N):
        graph[i].append(A[i] - 1)

    # Depth-first search to find a cycle
    def dfs(node, path):
        if node in path:
            return path[path.index(node):]
        path.append(node)
        for neighbor in graph[node]:
            cycle = dfs(neighbor, path)
            if cycle:
                return cycle
        path.pop()
        return []

    # Find a cycle starting from each node
    for i in range(N):
        cycle = dfs(i, [])
        if cycle:
            return len(cycle), ' '.join(map(str, cycle))

    return None

