from math import sqrt

def min_distance_with_penalty(N, checkpoints):
    if N == 2:
        return sqrt((checkpoints[1][0] - checkpoints[0][0]) ** 2 + (checkpoints[1][1] - checkpoints[0][1]) ** 2)

    min_s = float('inf')
    for i in range(1, N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                for l in range(k + 1, N):
                    path = [0, i, j, k, l, N - 1]
                    distance = sum(sqrt((checkpoints[path[i]][0] - checkpoints[path[i + 1]][0]) ** 2 + (checkpoints[path[i]][1] - checkpoints[path[i + 1]][1]) ** 2) for i in range(len(path) - 1))
                    penalty = 2 ** (len(path) - 5) if len(path) > 5 else 0
                    s = distance + penalty
                    min_s = min(min_s, s)
    return min_s

