        line_count = 1
        for length in L:
            if line_length + length + 1 > W:
                line_count += 1
                line_length = length
            else:
                line_length += length + 1
        return line_count <= M

    left, right = max(L), sum(L) + N - 1
    while left < right:
        mid = (left + right) // 2
