def solve(N, M, info):
    positions = [None] * (N + 1)
    positions[1] = (0, 0)

    for A, B, X, Y in info:
        if positions[A] is None:
            positions[A] = (X, Y)
        elif positions[B] is None:
            positions[B] = (X, Y)
        else:
            if positions[A] == positions[B]:
                return "undecidable"
            else:
                dx = positions[B][0] - positions[A][0]
                dy = positions[B][1] - positions[A][1]
                if dx == 0 and dy == 0:
                    return "undecidable"
                sx = X / dx
                sy = Y / dy
                if sx != sy:
                    return "undecidable"
                positions[B] = (positions[A][0] + sx * dx, positions[A][1] + sx * dy)

