def find_integer_root(b):
    if b < 2:
        return -1
    low, high = 1, int(math.sqrt(b)) + 1
    while low <= high:
        mid = (low + high) // 2
        power = mid ** mid
        if power == b:
            return mid
        elif power < b:
            low = mid + 1
        else:
            high = mid - 1
    return -1

