from collections import defaultdict

def solve(n, m, trains):
    graph = defaultdict(list)
    for l, d, k, c, a, b in trains:
        for t in range(l, l + k * d, d):
            graph[a].append((t, t + c, b))

    def dijkstra(start):
        dist = [-float('inf')] * n
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            current_dist, current_node = heapq.heappop(pq)
            if current_dist > dist[current_node]:
                continue
            for neighbor, travel_time, next_node in graph[current_node]:
                new_dist = current_dist + travel_time
                if new_dist > dist[next_node]:
                    dist[next_node] = new_dist
                    heapq.heappush(pq, (new_dist, next_node))
        return dist

    result = []
    for i in range(1, n):
        dist = dijkstra(i)
        if dist[n - 1] == -float('inf'):
            result.append('Unreachable')
        else:
            result.append(dist[n - 1])
    return result

