def kruskal(graph):
    edges = sorted(graph.items(), key=lambda item: item[1])
    parent = {i: i for i in range(1, len(graph) + 1)}
    mst_weight = 0
    mst_edges = 0
    for edge in edges:
        u, v, weight = edge
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            mst_weight += weight
            mst_edges += 1
            if mst_edges == len(graph) - 1:
                break
    return mst_weight if mst_edges == len(graph) - 1 else -1

