class Solution:
    def minimumMoves(self, nums: List[int], k: int, maxChanges: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        def get_sum(i, j):
            return prefix[j + 1] - prefix[i]

        dp = [[float('inf')] * (k + 1) for _ in range(n)]
        for i in range(n):
            for j in range(1, k + 1):
                if i - j < 0:
                    continue
                if j == 1:
                    dp[i][j] = get_sum(i, i)
                else:
                    for l in range(i - j + 1, i + 1):
                        if l - i + 1 > maxChanges:
                            break
                        dp[i][j] = min(dp[i][j], dp[l - 1][j - 1] + get_sum(l, i))
        return dp[n - 1][k]

