    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        primes = [num for num in nums if is_prime(num)]
        if len(primes) < 2:
            return 0

        max_diff = 0
        for i in range(len(primes)):
            for j in range(i + 1, len(primes)):
                max_diff = max(max_diff, primes[j] - primes[i])

        return max_diff

