        MOD = 10**9 + 7
        n = len(nums)

        @lru_cache(None)
        def dp(i, remaining):
            if remaining < 0:
                return 0
            if i == n:
                return 1 if remaining == 0 else 0

            # Include the current element
            include = dp(i + 1, remaining - nums[i]) % MOD
            # Exclude the current element
            exclude = dp(i + 1, remaining) % MOD

            return (include + exclude) % MOD

        return dp(0, k)

