        mod = 10**9 + 7

        @lru_cache(None)
        def dp(i, mask, length):
            if length == k:
                return 0
            if i == n:
                return float('inf')

            # Include nums[i] in the subsequence
            include = abs(nums[i] - nums[i - 1]) + dp(i + 1, mask | (1 << i), length + 1)
