class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (zero + one)
        dp[0] = 1

        for i in range(1, zero + one):
            if i >= zero:
                dp[i] = (dp[i] + dp[i - zero]) % MOD
            if i >= one:
                dp[i] = (dp[i] + dp[i - one]) % MOD
            if i > limit:
                dp[i] = (dp[i] - dp[i - limit - 1] + MOD) % MOD

        return sum(dp) % MOD

