def can_reach_state(N, S, T):
    # Check if the number of white stones in S and T are the same
    if S.count('W') != T.count('W'):
        return -1

    # Check if the number of black stones in S and T are the same
    if S.count('B') != T.count('B'):
        return -1

    # Check if the stones can be rearranged to match T
    for i in range(N):
        if S[i] != T[i]:
            # Find the position of the stone in T
            pos = T.index(S[i])
            # Check if the stone can be moved to the correct position
            if pos > i:
                return -1
            # Move the stone to the correct position
            for j in range(pos, i):
                S = S[:j] + S[j+1] + S[j]

    return 0

