def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def kruskal(graph):
    edges = sorted(graph, key=lambda x: x[2])
    parent = list(range(len(graph) + 1))
    mst = []
    cost = 0
    for edge in edges:
        u, v, w = edge
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            mst.append(edge)
            cost += w
    return cost if len(mst) == len(graph) - 1 else -1

