        n = len(target)
        dp = [0] * n
        for i in range(n):
            for j in range(i):
                if target[i] == target[j]:
                    dp[i] = max(dp[i], dp[j])
            dp[i] += costs[i]
        max_cost = max(dp)
        return max_cost if max_cost != float('-inf') else -1

class Solution:
    def minChanges(self, n: int, k: int) -> int:
        if n == k:
            return 0

        n_bin = bin(n)[2:]
        k_bin = bin(k)[2:]

        if len(n_bin) != len(k_bin):
            return -1

        changes = 0
        for i in range(len(n_bin)):
            if n_bin[i] != k_bin[i]:
                changes += 1

        return changes

