class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        count = Counter(s)
        ones = count['1']
        zeros = count['0']
        total = len(s)

        if ones >= zeros * zeros:
            return total * (total + 1) // 2

        result = 0
        left = 0
        for right, char in enumerate(s):
            if char == '1':
                ones -= 1
            else:
                zeros -= 1

            while ones < zeros * zeros:
                if s[left] == '1':
                    ones += 1
                else:
                    zeros += 1
                left += 1

            result += right - left + 1

        return result

