class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        graph = defaultdict(list)
        for u, v in queries:
            graph[u].append(v)
            graph[v].append(u)

        distances = [0] * n
        distances[0] = n - 1

        for u, v in queries:
            queue = deque([u])
            visited = set([u])
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        distances[neighbor] = distances[node] + 1
                        queue.append(neighbor)

        result = []
        for u, v in queries:
            result.append(distances[v])

        return result

