class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        position = 0
        direction = 0  # 0: right, 1: down, 2: left, 3: up
        visited = set()

        for command in commands:
            if command == "RIGHT":
                direction = (direction + 1) % 4
            elif command == "LEFT":
                direction = (direction - 1) % 4
            elif command == "DOWN":
                direction = (direction + 2) % 4
            elif command == "UP":
                direction = (direction - 2) % 4

            if direction == 0:
                position += 1
            elif direction == 1:
                position += n
            elif direction == 2:
                position -= 1
            elif direction == 3:
                position -= n

            if position in visited:
                return position
            visited.add(position)

        return position

