        count = [0, 0, 0]
        for num in nums:
            count[num % 3] += 1
        if count[0] == len(nums):
            return 0
        if count[1] == len(nums) or count[2] == len(nums):
            return len(nums) - count[1] - count[2]
        if count[1] == 0:
            return count[2] - (count[0] % 2)
        if count[2] == 0:
            return count[1] - (count[0] % 2)
        return min(count[1], count[2]) - (count[0] % 2)

