class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [[float('inf')] * (k + 1) for _ in range(k + 1)]
        count = [collections.Counter() for _ in range(k + 1)]

        for i in range(n):
            idx = i % k
            dp[idx][0] = 0
            for j in range(1, k + 1):
                dp[idx][j] = dp[idx][j - 1] + 1
                for num in count[j]:
                    dp[idx][j] = min(dp[idx][j], dp[(i - j) % k][num] + abs(nums[i] - num))
            count[j][nums[i]] += 1

        return dp[(n - 1) % k][0]

