class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def is_palindrome(row):
            return row == row[::-1]

        def flip_row(row):
            return [1 - x for x in row]

        def flip_col(col):
            return [grid[i][col] for i in range(m)]

        def count_flips(row):
            return sum(1 for i in range(n // 2) if row[i] != row[n - i - 1])

        def count_flips_col(col):
            return sum(1 for i in range(m // 2) if col[i] != col[m - i - 1])

        def flip_to_palindrome(row):
            return flip_row(row) if count_flips(row) % 2 == 1 else row

        def flip_to_palindrome_col(col):
            return flip_col(col) if count_flips_col(col) % 2 == 1 else col

        def flip_to_palindrome_grid(grid):
            return [flip_to_palindrome(row) for row in grid]

        def flip_to_palindrome_grid_col(grid):
            return [flip_to_palindrome_col(col) for col in zip(*grid)]

        def count_flips_grid(grid):
            return sum(count_flips(row) for row in grid)

        def count_flips_grid_col(grid):
            return sum(count_flips_col(col) for col in zip(*grid))

        def flip_to_palindrome_grid_min(grid):
            return min(count_flips_grid(grid), count_flips_grid_col(grid))

        return flip_to_palindrome_grid_min(grid)

