class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        times = [-1] * n

        def dfs(node, parent, time):
            if times[node] != -1:
                return times[node]

            if node % 2 == 0:
                times[node] = time + 1
                for neighbor in graph[node]:
                    if neighbor != parent:
                        times[node] = max(times[node], dfs(neighbor, node, time + 1))
            else:
                times[node] = time + 1
                for neighbor in graph[node]:
                    if neighbor != parent:
                        times[node] = max(times[node], dfs(neighbor, node, time + 1))

            return times[node]

        for i in range(n):
            if times[i] == -1:
                dfs(i, -1, 0)

        return times

