def vertical_writing(texts):
    max_length = max(len(text) for text in texts)
    result = [''] * max_length

    for i, text in enumerate(texts):
        for j, char in enumerate(text):
            result[j] += char
        result[i] += '*' * (max_length - len(text))

    return result

