def can_write_integers(N, M, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent, xor_sum):
        if len(graph[node]) == 1 and node != 1:
            return xor_sum == 0

        for neighbor in graph[node]:
            if neighbor != parent:
                if not dfs(neighbor, node, xor_sum ^ graph[node][0]):
