def xor_sum(A, M, K):
    n = len(A)
    MOD = 998244353

    def xor_subseq(seq):
        return sum(seq) ** K % MOD

    def xor_all_subseqs(A):
        total = 0
        for i in range(1, 1 << n):
            subseq = [A[j] for j in range(n) if (i & (1 << j))]
            if len(subseq) % M == 0:
                total += xor_subseq(subseq)
        return total % MOD

    return xor_all_subseqs(A)

