MOD = 998244353

def is_good_integer(n: int) -> bool:
    divisors = [i for i in range(1, n + 1) if n % i == 0]
    return sum(divisors) % 3 == 0

def count_sequences(n: int, m: int) -> int:
    if m == 1:
        return sum(1 for i in range(1, n + 1) if is_good_integer(i)) % MOD

    count = 0
    for i in range(1, n + 1):
        if is_good_integer(i):
            count += count_sequences(n // i, m - 1)
            count %= MOD
    return count

