def min_lexicographical_array(S, T):
    if S == T:
        return 0, [S]

    n = len(S)
    result = []
    for i in range(n):
        if S[i] != T[i]:
            result.append(S[:i] + T[i] + S[i+1:])
            break

    return 1, result

