import sys

def process_queries(H, W, Q, queries):
    grid = [[1] * W for _ in range(H)]
    remaining_walls = H * W

    for R_q, C_q in queries:
        if grid[R_q - 1][C_q - 1] == 1:
            grid[R_q - 1][C_q - 1] = 0
            remaining_walls -= 1
        else:
            for i in range(R_q - 1, -1, -1):
                if grid[i][C_q - 1] == 1:
                    grid[i][C_q - 1] = 0
                    remaining_walls -= 1
                    break
            for i in range(R_q, H):
                if grid[i][C_q - 1] == 1:
                    grid[i][C_q - 1] = 0
                    remaining_walls -= 1
                    break
            for j in range(C_q - 1, -1, -1):
                if grid[R_q - 1][j] == 1:
                    grid[R_q - 1][j] = 0
                    remaining_walls -= 1
                    break
            for j in range(C_q, W):
                if grid[R_q - 1][j] == 1:
                    grid[R_q - 1][j] = 0
                    remaining_walls -= 1
                    break

    return remaining_walls

