def is_isomorphic(G, H, A):
    N = len(G)
    G_edges = set((u, v) for u, v in G)
    H_edges = set((a, b) for a, b in H)

    if G_edges != H_edges:
        return float('inf')

    for perm in permutations(range(1, N + 1)):
        if all((perm[u - 1], perm[v - 1]) in H_edges for u, v in G):
            return sum(A[i - 1][j - 1] for i, j in G)

    return float('inf')

