        return (p1[0] - q1[0]) * (p2[1] - q1[1]) == (p2[0] - q1[0]) * (p1[1] - q1[1])

    n = len(points)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if is_intersecting(points[i], points[j], points[k], points[queries[i][0] - 1]):
                    return False
                if is_intersecting(points[i], points[j], points[k], points[queries[j][0] - 1]):
                    return False
                if is_intersecting(points[i], points[j], points[k], points[queries[k][0] - 1]):
                    return False
    return True

