class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            return str(k)

        def is_palindrome(s):
            return s == s[::-1]

        def is_divisible_by_k(s, k):
            return int(s) % k == 0

        if n % 2 == 0:
            left = int('1' * (n // 2))
            right = int('1' * (n // 2))
        else:
            left = int('1' * (n // 2))
            right = int('1' * (n // 2)) + 1

        while left <= right:
            mid = (left + right) // 2
            candidate = str(mid) + str(mid)[::-1]
            if is_palindrome(candidate) and is_divisible_by_k(candidate, k):
                return candidate
            right -= 1

        return str(k) * n

