class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        n = len(nums)
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, k + 1):
                dp[i][j] = max(dp[i - 1][j] + nums[i - 1] * multiplier, dp[i][j - 1] + nums[n - j] * multiplier)

        result = []
        i, j = n, k
        while i > 0 and j > 0:
            if dp[i - 1][j] + nums[i - 1] * multiplier > dp[i][j - 1] + nums[n - j] * multiplier:
                result.append(nums[i - 1] * multiplier)
                i -= 1
            else:
                result.append(nums[n - j] * multiplier)
                j -= 1
        result.reverse()
        return result

