class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        results = []
        obstacles = []

        for x, y in queries:
            heapq.heappush(obstacles, (abs(x) + abs(y), x, y))
            if len(obstacles) > k:
                heapq.heappop(obstacles)
            if len(obstacles) == k:
                results.append(obstacles[0][1] + obstacles[0][2])
            else:
                results.append(-1)

        return results

