class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        def build_trie(nums):
            trie = {}
            for num in nums:
                node = trie
                for bit in reversed(bin(num)[2:]):
                    if bit not in node:
                        node[bit] = {}
                    node = node[bit]
            return trie

        def query_trie(trie, num):
            node = trie
            xor = 0
            for bit in reversed(bin(num)[2:]):
                if '1' - bit in node:
                    xor = (xor << 1) | 1
                    node = node['1' - bit]
                else:
                    xor <<= 1
                    node = node[bit]
            return xor

        trie = build_trie(nums)
        queries = sorted([(num, l, r) for l, r, num in enumerate(queries)], key=lambda x: x[0])
        result = [-1] * len(queries)
        i = 0
        for num, l, r in queries:
            while i < len(nums) and nums[i] <= num:
                query_trie(trie, nums[i])
                i += 1
            result[l] = max(result[l], query_trie(trie, num))
        return result

