class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        board = [[0] * 50 for _ in range(50)]
        for i, (x, y) in enumerate(positions):
            board[x][y] = i

        def knight_moves(x, y):
            moves = [
                (x + 2, y + 1), (x + 2, y - 1),
                (x - 2, y + 1), (x - 2, y - 1),
                (x + 1, y + 2), (x + 1, y - 2),
                (x - 1, y + 2), (x - 1, y - 2)
            ]
            return [(nx, ny) for nx, ny in moves if 0 <= nx < 50 and 0 <= ny < 50]

        def bfs(start_x, start_y):
            queue = [(start_x, start_y, 0)]
            visited = set()
            visited.add((start_x, start_y))
            max_moves = 0
            while queue:
                x, y, moves = queue.pop(0)
                if board[x][y] != 0:
                    max_moves = max(max_moves, moves)
                    continue
                for nx, ny in knight_moves(x, y):
                    if (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny, moves + 1))
            return max_moves

        total_moves = 0
        for i in range(n):
            total_moves += bfs(positions[i][0], positions[i][1])
        return total_moves

