class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        prefix_count = [0] * 26
        suffix_count = [0] * 26

        for word in words:
            for i, char in enumerate(word):
                suffix_count[ord(char) - ord('a')] += 1

        result = 0
        current_prefix = ""

        for i in range(n):
            found = False
            for j in range(len(words)):
                if words[j].startswith(current_prefix + target[i]):
                    current_prefix += target[i]
                    suffix_count[ord(target[i]) - ord('a')] -= 1
                    found = True
                    break
            if not found:
                return -1

            for k in range(26):
                if suffix_count[k] < 0:
                    for l in range(len(words)):
                        if words[l].endswith(target[i]):
                            suffix_count[k] += 1
                            current_prefix = words[l][:-len(target[i])]
                            break
                    else:
                        return -1

            result += 1

        return result

