class Solution:
    def stringHash(self, s: str, k: int) -> str:
        result = ""
        for i in range(0, len(s), k):
            substring = s[i:i+k]
            hash_value = sum(ord(char) - ord('a') for char in substring)
            hashed_char = chr((hash_value % 26) + ord('a'))
            result += hashed_char
        return result

