            return num_str == num_str[::-1] and num % k == 0

        def count_good_integers(start: int, end: int) -> int:
            if start > end:
                return 0
            if start == end:
                return 1 if is_k_palindrome(start) else 0

            count = 0
            for i in range(10):
                if i == 0 and start == 0:
                    continue
                count += count_good_integers(start * 10 + i, end)
            return count

        return count_good_integers(0, 10 ** n - 1)

