class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])

        def dfs(x, y, h):
            if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == 1 and h <= 0:
                return False
            if x == m - 1 and y == n - 1:
                return h >= 1
            grid[x][y] = 1  # Mark as visited
            h -= 1
            result = dfs(x + 1, y, h) or dfs(x - 1, y, h) or dfs(x, y + 1, h) or dfs(x, y - 1, h)
            grid[x][y] = 0  # Backtrack
            return result

        return dfs(0, 0, health)

