import math

def min_time_to_print_segments(N, S, T, segments):
    def distance(p1, p2):
        return math.sqrt((p2[0] - p1[0]) ** 2 + (p2[1] - p1[1]) ** 2)

    def time_to_move_to_endpoint(p1, p2):
        return distance(p1, p2) / S

    def time_to_print_segment(p1, p2):
        if p1 == p2:
            return 0
        if p1[0] == p2[0]:
            return abs(p2[1] - p1[1]) / T
        if p1[1] == p2[1]:
            return abs(p2[0] - p1[0]) / T
        return distance(p1, p2) / T

    total_time = 0
    for i in range(N):
        p1, p2 = segments[i]
        total_time += time_to_move_to_endpoint((0, 0), p1)
        total_time += time_to_print_segment(p1, p2)
        total_time += time_to_move_to_endpoint(p2, p2)
    return total_time

