                end = i
                blocks.append((start, end))
                start = i + 1
    if len(blocks) < K:
        raise ValueError("S contains fewer than K 1-blocks")
    kth_block = blocks[K - 1]
    new_blocks = blocks[:K - 1] + blocks[K:]
    new_blocks.append((kth_block[0], kth_block[1] + kth_block[1] - kth_block[0] + 1))
    result = []
