def can_transform(S, T, K):
    if len(S) > len(T):
        return "No"

    # Try to match characters from the end of S to the end of T
    i, j = len(S) - 1, len(T) - 1
    while i >= 0 and j >= 0:
        if S[i] == T[j]:
            i -= 1
            j -= 1
        else:
            if K == 0:
                return "No"
            if i > 0 and S[i] == T[j - 1]:
                i -= 1
            elif i > 0 and S[i - 1] == T[j]:
                i -= 1
            elif i > 0 and S[i] == T[j] and S[i - 1] == T[j - 1]:
                i -= 1
            else:
                return "No"
            K -= 1

    # If S is exhausted, check if the remaining characters in T can be inserted
    while j >= 0:
        if K == 0:
            return "No"
        K -= 1
        j -= 1

    return "Yes"

