class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        def gcd_lcm(a, b):
            return gcd(a, b), lcm(a, b)

        def factor_score(arr):
            if not arr:
                return 0
            g, l = arr[0], arr[0]
            for num in arr[1:]:
                g, l = gcd_lcm(g, num)
            return g * l

        max_score = 0
        for i in range(n):
            current_score = factor_score(nums[:i] + nums[i+1:])
            max_score = max(max_score, current_score)

        return max_score

