class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        for i in range(n):
            if nums[i] == 0:
                left = i - 1
                right = i + 1
                direction = 1  # 1 for right, -1 for left

                while left >= 0 or right < n:
                    if left >= 0 and nums[left] == 0:
                        left -= 1
                    elif right < n and nums[right] == 0:
                        right += 1
                    else:
                        if nums[left] > 0:
                            nums[left] -= 1
                            direction *= -1
                            left -= direction
                        elif nums[right] > 0:
                            nums[right] -= 1
                            direction *= -1
                            right += direction
                        else:
                            count += 1
                            break

        return count

