class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(node, parent, weight):
            nonlocal max_weight
            children_weights = []
            for neighbor, w in graph[node]:
                if neighbor != parent:
                    children_weights.append(dfs(neighbor, node, w))
            children_weights.sort(reverse=True)
            if len(children_weights) > k:
                children_weights = children_weights[:k]
            max_weight = max(max_weight, sum(children_weights) + weight * (len(children_weights) + 1))
            return weight + sum(children_weights)

        max_weight = 0
        dfs(0, -1, 0)
        return max_weight

