        n = len(fruits)
        max_fruits = 0

        # Directions for moving from (i, j) to (i + 1, j + 1), (i + 1, j), and (i, j + 1)
        directions = [(1, 1), (1, 0), (0, 1)]

        # Iterate over all possible starting positions
        for i in range(n):
            for j in range(n):
                # Try all possible paths for each starting position
                for dx, dy in directions:
                    current_fruits = 0
                    x, y = i, j
                    for _ in range(n - 1):
                        x += dx
                        y += dy
                        if 0 <= x < n and 0 <= y < n:
