class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(num):
            if num <= 1:
                return False
            if num <= 3:
                return True
            if num % 2 == 0 or num % 3 == 0:
                return False
            i = 5
            while i * i <= num:
                if num % i == 0 or num % (i + 2) == 0:
                    return False
                i += 6
            return True

        def cost_to_transform(n, m):
            cost = 0
            while n != m:
                if is_prime(n):
                    return -1
                if n < m:
                    n += 1
                else:
                    n -= 1
                cost += n
            return cost

        return cost_to_transform(n, m)

