                    if pair[0] == start and pair[1] == target:
                        memo[(start, target, day)] = rates2[i]
                        return rates2[i]
            memo[(start, target, day)] = 0.0
            for i, pair in enumerate(pairs1):
                if pair[0] == start:
                    memo[(start, target, day)] = max(memo[(start, target, day)], convert(pair[1], target, 1) * rates1[i])
            for i, pair in enumerate(pairs2):
                if pair[0] == start:
                    memo[(start, target, day)] = max(memo[(start, target, day)], convert(pair[1], target, 2) * rates2[i])
            return memo[(start, target, day)]

        memo = {}
        return convert(initialCurrency, initialCurrency, 1) * 1.0

