class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if numOps >= n:
            return 1

        left = 0
        right = 0
        max_length = n
        current_length = 0
        current_count = 0
        current_char = s[0]

        while right < n:
            if s[right] == current_char:
                current_length += 1
                current_count += 1
            else:
                current_char = s[right]
                current_length = 1
                current_count = 1

            if current_count > numOps:
                max_length = min(max_length, n - current_length)
                while left <= right and current_count > numOps:
                    if s[left] == current_char:
                        current_count -= 1
                    left += 1
                current_length = right - left + 1
                current_count = right - left + 1

            right += 1

        return min(max_length, n - current_length)

