        # Calculate the area of each rectangle
        areas = set()
        for x1, y1, x2, y2 in rectangles:
            areas.add((x2 - x1) * (y2 - y1))

        # Check if there are at least two unique areas
        if len(areas) < 2:
            return False

        # Check if there are at least two unique heights
        heights = set()
        for x1, y1, x2, y2 in rectangles:
            heights.add(y2 - y1)
        if len(heights) < 2:
            return False

        # Check if there are at least two unique widths
        widths = set()
        for x1, y1, x2, y2 in rectangles:
            widths.add(x2 - x1)
